
// Límites entre provincias y costas, extraídos de la topología nativa de Earth3.
// Formato binario comprimido: pid, vecino, número de puntos, punto inicial y deltas.
window.__LTA_BORDER_GZIP_BASE64="";
window.__LTA_BORDER_DATA_PROMISE=null;
window.__LTA_LOAD_BORDER_DATA=()=>{
 if(!window.__LTA_BORDER_PAYLOAD_READY){window.__LTA_BORDER_PAYLOAD_READY=window.LTA.loadScript('data/earth3-borders.js');}
 return window.__LTA_BORDER_PAYLOAD_READY.then(()=>window.__LTA_DECODE_BORDER_DATA());
};
window.__LTA_DECODE_BORDER_DATA=()=>{
 if(window.__LTA_BORDER_DATA_PROMISE)return window.__LTA_BORDER_DATA_PROMISE;
 window.__LTA_BORDER_DATA_PROMISE=(async()=>{
  if(!('DecompressionStream' in window)) throw new Error('Este navegador no admite la carga comprimida de los límites territoriales.');
  const t0=performance.now(),binary=atob(window.__LTA_BORDER_GZIP_BASE64),bytes=new Uint8Array(binary.length);
  for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
  const raw=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());
  const view=new DataView(raw.buffer,raw.byteOffset,raw.byteLength),records=[];let o=0;
  while(o+10<=raw.length){
    const a=view.getUint16(o,true),b=view.getUint16(o+2,true),n=view.getUint16(o+4,true);
    let x=view.getInt16(o+6,true),y=view.getInt16(o+8,true);o+=10;
    if(n<2||o+(n-1)*4>raw.length)break;
    const line=[[x,y]];
    for(let i=1;i<n;i++){x+=view.getInt16(o,true);y+=view.getInt16(o+2,true);o+=4;line.push([x,y]);}
    records.push([a,b,line]);
  }
  console.info('[LTA rendimiento] Límites nativos cargados',{tramos:records.length,ms:+(performance.now()-t0).toFixed(1)});
  return records;
 })();
 return window.__LTA_BORDER_DATA_PROMISE;
};
